entries[330132] = { ["name"] = "Arie der Nebelruferin", ["text"] = "Sofort\nSpielt eine Melodie und hebt das Gemüt Eurer Verbündeten für 15 Min. Euer Lied gewährt den Fähigkeiten Eurer Verbündeten eine geringe Chance, ihnen 15 Sek. lang 56 Vielseitigkeit zu gewähren." }
entries[330133] = { ["name"] = "Konzentrierte Seuche", ["text"] = "Sofort\nBei erlittenen Treffern quillt Galle aus der Kreatur, die an zufälligen Orten toxische Lachen bildet. Gegner, die sich in den Lachen aufhalten, erleiden alle 1 Sek. 15 Naturschaden." }
entries[330134] = { ["name"] = "Relikt der Vergangenheit I", ["text"] = "Wirken in 1.5 sek.\nTools: Schmiedehammer\nReagenzien:\nKupfererz (5), Leuchtender Fluxus\nStellt ein Relikt der Vergangenheit I her.\nBerufsausbilder:\nKlassische Schmiedekunst (1)\nKosten:\n10\n\nOptionales Handwerksmaterial\n\nBenutzbar mit: Viele Ausrüstungsrezepte von vor der aktuellen Erweiterung.\n\"Erhältlich bei vielen Handwerkswarenverkäufern in ganz Azeroth und darüber hinaus. Kann im Auktionshaus verkauft und erworben werden.\"" }
entries[330135] = { ["name"] = "Quelle der Pestilenz", ["text"] = "Sofort\nInflicts 10 Nature damage to an enemy every 1 sec for 5 Sek.." }
entries[330136] = { ["name"] = "Entschlossenheit", ["text"] = "Erhöht Eure auf Euch selbst gewirkte Heilung und Absorption abhängig vom innerhalb der letzten 10 Sek. erlittenen Schaden (vor Vermeidung und Mitigation)." }
entries[330137] = { ["name"] = "Massaker", ["text"] = "Unbegrenzte Reichweite\nSofort\nRemornia entfesselt ihre gesamte Macht, um massive Klingen zu erschaffen, die in alle Richtungen schlagen und getroffenen Spielercharakteren 177767 Schattenschaden zufügen." }
