entries[330382] = { ["name"] = "Ascheweihung", ["text"] = "Sofort\nWeiht den Zielbereich für 30 Sek. Gegner innerhalb des Bereichs erleiden bis zu [(55% der Zaubermacht) * 30 / 2] Schattenschaden und Verbündete werden um bis zu [(36% der Zaubermacht) * 30 / 2] Gesundheit geheilt. Die Werte verringern sich bei mehr als 5 Zielen.\n\nInnerhalb der Weihung könnt Ihr 'Hammer des Zorns' gegen jedes beliebige Ziel einsetzen und die Fähigkeit verursacht 100% mehr Schaden.\n(100ms Abklingzeit)" }
