entries[330895] = { ["name"] = "Geisterschritt", ["text"] = "Sofort\nBei erlittenen Treffern quillt Galle aus der Kreatur, die an zufälligen Orten toxische Lachen bildet. Gegner, die sich in den Lachen aufhalten, erleiden alle 1 Sek. 15 Naturschaden.\n(20s Abklingzeit)" }
entries[330896] = { ["name"] = "Straße der Prüfungen", ["text"] = "100 Meter Reichweite\nSofort\nNachdem Ihr einen Gegner besiegt habt, erhaltet Ihr 20 Sek. lang 10% Bewegungsgeschwindigkeit. Dieser Effekt verstärkt sich, wenn Ihr einen mächtigen Gegner besiegt." }
entries[330897] = { ["name"] = "Greifende Tentakel", ["text"] = "Animabonus\nSofort\nDie ersten 3 erlittenen Nahkampfangriffe bei aktiver 'Baumrinde' oder 'Eisenborke' lösen bei Angreifern 'Wucherwurzeln' aus." }
entries[330898] = { ["name"] = "Furorfäuste", ["text"] = "8 Meter Reichweite\nKanalisiert (Wirken in 3 sek.) 24 sek. Abklingzeit\nVerprügelt alle Ziele vor Euch mit schnellen Faustangriffen, die Eurem Primärziel im Verlauf von 3 Sek. [5 * (120.75% der Angriffskraft)] körperlichen Schaden und bis zu 5 anderen Zielen im Verlauf von 3 Sek. [5 * (120.75% der Angriffskraft) * 50 / 100] Schaden zufügen." }
entries[330901] = { ["name"] = "Wirbelnder Kranichtritt", ["text"] = "2 Chi / 1% von Grundmana / 25 Energie\nKanalisiert (Wirken in 1.5 sek.)\nWindläufer\nIhr dreht Euch in der Luft, während Ihr Tritte ausführt, die bis zu 6 Gegnern innerhalb von 8 Metern im Verlauf von 1.5 Sek. [4 * (10% der Angriffskraft) * [(Angriffskraft * 0.98)][((Angriffskraft + Schildhand-Angriffskraft) * 2 / 3)] -- 2H, DW / Angriffskraft] körperlichen Schaden zufügen.\n\nDer Schaden von 'Wirbelnder Kranichtritt' wird für jedes einzelne Ziel, das Ihr innerhalb der letzten 20 Sek. mit 'Tigerklaue', 'Blackout-Tritt' oder 'Tritt der aufgehenden Sonne' getroffen habt, um 18% erhöht.\n\nBraumeister, Nebelwirker\nIhr dreht Euch in der Luft, während Ihr Tritte ausführt, die bis zu 6 Gegnern innerhalb von 8 Metern im Verlauf von 1.5 Sek. [4 * (10% der Angriffskraft)] körperlichen Schaden zufügen." }
entries[330902] = { ["name"] = "Nach oben teleportieren" }
entries[330903] = { ["name"] = "Wirbelnder Kranichtritt", ["text"] = "Sofort\nWindläufer\nIhr dreht Euch in der Luft, während Ihr Tritte ausführt, die allen Gegnern innerhalb von 8 Metern im Verlauf von 1.5 Sek. [4 * (10% der Angriffskraft) * [(Angriffskraft * 0.98)][((Angriffskraft + Schildhand-Angriffskraft) * 2 / 3)] -- 2H, DW / Angriffskraft] körperlichen Schaden zufügen. Fügt Zielen über 5 Ziele hinaus verringerten Schaden zu.\n\nBraumeister, Nebelwirker\nIhr dreht Euch in der Luft, während Ihr Tritte ausführt, die allen Gegnern innerhalb von 8 Metern im Verlauf von 1.5 Sek. [4 * (10% der Angriffskraft)] körperlichen Schaden zufügen. Fügt Zielen über 5 Ziele hinaus verringerten Schaden zu." }
entries[330904] = { ["name"] = "Rottholzskarabäus", ["text"] = "Animabonus\nSofort\nWenn 'Wucherwurzeln' aufgehoben wird, findet eine Explosion statt, die allen Gegnern in der Nähe (150% der Zaubermacht) Naturschaden zufügt." }
