entries[330907] = { ["name"] = "Feuerodem", ["text"] = "Sofort 15 sek. Abklingzeit\nÜberzieht Ziele vor Euch mit Feueratem und fügt ihnen (28.5012% der Angriffskraft) Feuerschaden zu.\n\nZiele, die von 'Fasshieb' betroffen sind, brennen außerdem, wodurch sie (33.3% der Angriffskraft) Feuerschaden erleiden und Euch 5% weniger Schaden zufügen. Hält 12 Sek. lang an." }
entries[330908] = { ["name"] = "Theater of Pain - Teleporter to the Top Cosmetics" }
